'use strict';
const APP_CACHE='atlas-app-v6-live',MAP_CACHE='atlas-ukraine-roads-20260921-z11-v1';
const APP_FILES=['./','index.html','style.css','app.js','data-loader.js','offline-map.js','data.json','online-style.json','map/manifest.json','vendor/equipment-icons.js','vendor/leaflet.js','vendor/leaflet.css','vendor/protomaps-leaflet.js','vendor/pmtiles.js','vendor/maplibre-gl.js','vendor/maplibre-gl.css','vendor/leaflet-maplibre-gl.js'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(APP_CACHE).then(c=>c.addAll(APP_FILES)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('atlas-app-')&&k!==APP_CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',e=>{const url=new URL(e.request.url);if(url.origin!==location.origin||e.request.method!=='GET')return;if(url.pathname.includes('/map/part-')){e.respondWith(caches.open(MAP_CACHE).then(async c=>{const hit=await c.match(e.request);if(hit)return hit;return fetch(e.request)}));return}e.respondWith((async()=>{try{const response=await fetch(e.request);if(response.ok){const c=await caches.open(APP_CACHE);await c.put(e.request,response.clone())}return response}catch{const c=await caches.open(APP_CACHE);return await c.match(e.request)||(e.request.mode==='navigate'?await c.match('./'):undefined)||new Response('Offline resource unavailable',{status:503})}})())});
